// ============================================================================
// RAPIDIO_apb: APB4 register wrapper around RAPIDIO_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/RAPIDIO.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/RAPIDIO.md
// ============================================================================
module RAPIDIO_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic rx_valid,
  input logic [7:0] rx_data,
  input logic rx_last,
  output logic tx_valid,
  output logic [7:0] tx_data,
  output logic tx_last
);
  localparam logic [31:0] ID_VALUE = 32'h52490100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [22:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd23) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic [31:0]   c_cfg_dev_id_car;
  logic [31:0]   c_cfg_dev_info_car;
  logic [31:0]   c_cfg_asm_id_car;
  logic [31:0]   c_cfg_asm_info_car;
  logic [31:0]   c_cfg_pe_feat_car;
  logic [23:0]   c_cfg_base_id;
  logic          c_id_load;
  logic [23:0]   c_base_id;
  logic          c_host_rd;
  logic          c_host_wr;
  logic [9:0]    c_host_addr;
  logic [7:0]    c_host_wdata;
  logic [7:0]    c_host_rdata;
  logic          c_ob_start;
  logic          c_ob_tt;
  logic [15:0]   c_ob_dest;
  logic [7:0]    c_ob_tid;
  logic [15:0]   c_ob_info;
  logic          c_ob_busy;
  logic          c_ob_done;
  logic [3:0]    c_ob_status;
  logic          c_db_valid;
  logic [15:0]   c_db_src;
  logic [7:0]    c_db_tid;
  logic [15:0]   c_db_info;
  logic          c_rx_rep;
  logic [2:0]    c_rx_why;
  logic [3:0]    c_rx_ftype;
  logic          c_busy;
  RAPIDIO_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .rx_valid(rx_valid),
    .rx_data(rx_data),
    .rx_last(rx_last),
    .tx_valid(tx_valid),
    .tx_data(tx_data),
    .tx_last(tx_last),
    .cfg_dev_id_car(c_cfg_dev_id_car),
    .cfg_dev_info_car(c_cfg_dev_info_car),
    .cfg_asm_id_car(c_cfg_asm_id_car),
    .cfg_asm_info_car(c_cfg_asm_info_car),
    .cfg_pe_feat_car(c_cfg_pe_feat_car),
    .cfg_base_id(c_cfg_base_id),
    .id_load(c_id_load),
    .base_id(c_base_id),
    .host_rd(c_host_rd),
    .host_wr(c_host_wr),
    .host_addr(c_host_addr),
    .host_wdata(c_host_wdata),
    .host_rdata(c_host_rdata),
    .ob_start(c_ob_start),
    .ob_tt(c_ob_tt),
    .ob_dest(c_ob_dest),
    .ob_tid(c_ob_tid),
    .ob_info(c_ob_info),
    .ob_busy(c_ob_busy),
    .ob_done(c_ob_done),
    .ob_status(c_ob_status),
    .db_valid(c_db_valid),
    .db_src(c_db_src),
    .db_tid(c_db_tid),
    .db_info(c_db_info),
    .rx_rep(c_rx_rep),
    .rx_why(c_rx_why),
    .rx_ftype(c_rx_ftype),
    .busy(c_busy)
  );

  // ---------------- registers ----------------
  logic [5:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [31:0] r_DEV_ID_CAR;   // 12'h014 DEV_ID_CAR
  logic [31:0] r_DEV_INFO_CAR;   // 12'h018 DEV_INFO_CAR
  logic [31:0] r_ASM_ID_CAR;   // 12'h01C ASM_ID_CAR
  logic [31:0] r_ASM_INFO_CAR;   // 12'h020 ASM_INFO_CAR
  logic [31:0] r_PE_FEAT_CAR;   // 12'h024 PE_FEAT_CAR
  logic [23:0] r_BASE_ID_CFG;   // 12'h028 BASE_ID_CFG
  logic [9:0] r_MEM_ADDR;   // 12'h02C MEM_ADDR
  logic [7:0] r_MEM_WDATA;   // 12'h030 MEM_WDATA
  logic [24:0] r_OB_CTRL;   // 12'h034 OB_CTRL
  logic [15:0] r_OB_INFO;   // 12'h038 OB_INFO
  logic [3:0] p_CMD;   // 12'h03C CMD (pulses)
  logic [6:0] h_RX_REP;   // 12'h04C RX_REP holding register
  logic [23:0] h_DOORBELL0;   // 12'h050 DOORBELL0 holding register
  logic [15:0] h_DOORBELL1;   // 12'h054 DOORBELL1 holding register
  logic [3:0] h_OB_DONE;   // 12'h058 OB_DONE holding register
  logic avail_RX_REP;
  logic avail_DOORBELL;
  logic avail_OB_DONE;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_DEV_ID_CAR <= 32'h0;
      r_DEV_INFO_CAR <= 32'h0;
      r_ASM_ID_CAR <= 32'h0;
      r_ASM_INFO_CAR <= 32'h0;
      r_PE_FEAT_CAR <= 32'h0;
      r_BASE_ID_CFG <= 24'h0;
      r_MEM_ADDR <= 10'h0;
      r_MEM_WDATA <= 8'h0;
      r_OB_CTRL <= 25'h0;
      r_OB_INFO <= 16'h0;
      p_CMD <= '0;
      h_RX_REP <= '0;
      h_DOORBELL0 <= '0;
      h_DOORBELL1 <= '0;
      h_OB_DONE <= '0;
      avail_RX_REP <= 1'b0;
      avail_DOORBELL <= 1'b0;
      avail_OB_DONE <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[5:0] & wmask[5:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[5:0]) | (PWDATA[5:0] & wmask[5:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_DEV_ID_CAR <= (r_DEV_ID_CAR & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[6]) r_DEV_INFO_CAR <= (r_DEV_INFO_CAR & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[7]) r_ASM_ID_CAR <= (r_ASM_ID_CAR & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[8]) r_ASM_INFO_CAR <= (r_ASM_INFO_CAR & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[9]) r_PE_FEAT_CAR <= (r_PE_FEAT_CAR & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[10]) r_BASE_ID_CFG <= (r_BASE_ID_CFG & ~wmask[23:0]) | (PWDATA[23:0] & wmask[23:0]);
      if (wr && hit[11]) r_MEM_ADDR <= (r_MEM_ADDR & ~wmask[9:0]) | (PWDATA[9:0] & wmask[9:0]);
      if (wr && hit[12]) r_MEM_WDATA <= (r_MEM_WDATA & ~wmask[7:0]) | (PWDATA[7:0] & wmask[7:0]);
      if (wr && hit[13]) r_OB_CTRL <= (r_OB_CTRL & ~wmask[24:0]) | (PWDATA[24:0] & wmask[24:0]);
      if (wr && hit[14]) r_OB_INFO <= (r_OB_INFO & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      p_CMD <= (wr && hit[15]) ? PWDATA[3:0] & wmask[3:0] : '0;
      if (c_rx_rep && (!avail_RX_REP || (rd && hit[19]))) begin
        h_RX_REP[2:0] <= c_rx_why[2:0];
        h_RX_REP[6:3] <= c_rx_ftype[3:0];
        avail_RX_REP <= 1'b1;
      end else if (rd && hit[19]) avail_RX_REP <= 1'b0;
      if (c_db_valid && (!avail_DOORBELL || (rd && hit[21]))) begin
        h_DOORBELL0[15:0] <= c_db_info[15:0];
        h_DOORBELL0[23:16] <= c_db_tid[7:0];
        h_DOORBELL1[15:0] <= c_db_src[15:0];
        avail_DOORBELL <= 1'b1;
      end else if (rd && hit[21]) avail_DOORBELL <= 1'b0;
      if (c_ob_done && (!avail_OB_DONE || (rd && hit[22]))) begin
        h_OB_DONE[3:0] <= c_ob_status[3:0];
        avail_OB_DONE <= 1'b1;
      end else if (rd && hit[22]) avail_OB_DONE <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_cfg_dev_id_car = r_DEV_ID_CAR[31:0];
  assign c_cfg_dev_info_car = r_DEV_INFO_CAR[31:0];
  assign c_cfg_asm_id_car = r_ASM_ID_CAR[31:0];
  assign c_cfg_asm_info_car = r_ASM_INFO_CAR[31:0];
  assign c_cfg_pe_feat_car = r_PE_FEAT_CAR[31:0];
  assign c_cfg_base_id = r_BASE_ID_CFG[23:0];
  assign c_host_addr = r_MEM_ADDR[9:0];
  assign c_host_wdata = r_MEM_WDATA[7:0];
  assign c_ob_dest = r_OB_CTRL[15:0];
  assign c_ob_tid = r_OB_CTRL[23:16];
  assign c_ob_tt = r_OB_CTRL[24:24];
  assign c_ob_info = r_OB_INFO[15:0];
  assign c_id_load = p_CMD[0:0];
  assign c_host_wr = p_CMD[1:1];
  assign c_host_rd = p_CMD[2:2];
  assign c_ob_start = p_CMD[3:3];

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_rx_rep & (~avail_RX_REP | (rd & hit[19]));
    irq_set[1] = c_rx_rep & avail_RX_REP & ~(rd & hit[19]);
    irq_set[2] = c_db_valid & (~avail_DOORBELL | (rd & hit[21]));
    irq_set[3] = c_db_valid & avail_DOORBELL & ~(rd & hit[21]);
    irq_set[4] = c_ob_done & (~avail_OB_DONE | (rd & hit[22]));
    irq_set[5] = c_ob_done & avail_OB_DONE & ~(rd & hit[22]);
  end
  assign irq = |(irq_status & irq_enable);
  wire [2:0] flags = {avail_OB_DONE, avail_DOORBELL, avail_RX_REP};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_DEV_ID_CAR);
      10'd6: apb_rdata = 32'(r_DEV_INFO_CAR);
      10'd7: apb_rdata = 32'(r_ASM_ID_CAR);
      10'd8: apb_rdata = 32'(r_ASM_INFO_CAR);
      10'd9: apb_rdata = 32'(r_PE_FEAT_CAR);
      10'd10: apb_rdata = 32'(r_BASE_ID_CFG);
      10'd11: apb_rdata = 32'(r_MEM_ADDR);
      10'd12: apb_rdata = 32'(r_MEM_WDATA);
      10'd13: apb_rdata = 32'(r_OB_CTRL);
      10'd14: apb_rdata = 32'(r_OB_INFO);
      10'd16: apb_rdata = 32'({c_host_rdata});
      10'd17: apb_rdata = 32'({c_base_id});
      10'd18: apb_rdata = 32'({c_busy, c_ob_busy});
      10'd19: apb_rdata = 32'(h_RX_REP);
      10'd20: apb_rdata = 32'(h_DOORBELL0);
      10'd21: apb_rdata = 32'(h_DOORBELL1);
      10'd22: apb_rdata = 32'(h_OB_DONE);
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
